111	const cacheRemoteOutbound = <T extends ProviderMessageRecord | undefined>(
112	  remote: AdvancedIMessage,
113	  space: { id: string; phone: string; type: "dm" | "group" },
114	  record: T
115	): T => {
116	  if (!record) {
117	    return record;
118	  }
119	  cacheMessage(getMessageCache(remote), {
120	    ...record,
121	    direction: record.direction ?? "outbound",
122	    space: {
123	      ...record.space,
124	      id: record.space.id,
125	      phone: space.phone,
126	      type: space.type,
127	    },
128	  } as IMessageMessage);
129	  return record;
130	};
