132	const handleEdit = async (
133	  client: IMessageClient,
134	  space: { id: string; phone: string; type: "dm" | "group" },
135	  content: Edit
136	): Promise<void> => {
137	  const miniAppCardSession = (
138	    content.target as unknown as { miniAppCardSession?: MiniAppCardSession }
139	  ).miniAppCardSession;
140	  const updateMiniAppCardSession = (
141	    record: ProviderMessageRecord | undefined
142	  ): void => {
143	    const nextSession = record?.miniAppCardSession;
144	    if (nextSession) {
145	      (
146	        content.target as unknown as {
147	          miniAppCardSession?: MiniAppCardSession;
148	        }
149	      ).miniAppCardSession = nextSession as MiniAppCardSession;
150	    }
151	  };
152	  if (content.content.type === "app") {
153	    if (!miniAppCardSession) {
154	      throw UnsupportedError.content(
155	        "edit",
156	        "iMessage",
157	        "mini app card edits require a miniAppCardSession from the original send"
158	      );
159	    }
160	    const url = await content.content.url();
161	    const layout = await content.content.layout();
162	    const remote = clientForPhone(client, space.phone);
163	    const record = cacheRemoteOutbound(
164	      remote,
165	      space,
166	      await remoteUpdateCustomizedMiniApp(
167	        remote,
168	        space.id,
169	        miniAppCardSession,
170	        toSpectrumMiniApp(url, layout, content.content.live)
171	      )
172	    );
173	    updateMiniAppCardSession(record);
174	    return;
175	  }
176	  if (isCustomizedMiniApp(content.content)) {
177	    if (!miniAppCardSession) {
178	      throw UnsupportedError.content(
179	        "edit",
180	        "iMessage",
181	        "customized mini app card edits require a miniAppCardSession from the original send"
182	      );
183	    }
184	    const remote = clientForPhone(client, space.phone);
185	    const record = cacheRemoteOutbound(
186	      remote,
187	      space,
188	      await remoteUpdateCustomizedMiniApp(
189	        remote,
190	        space.id,
191	        miniAppCardSession,
192	        content.content
193	      )
194	    );
195	    updateMiniAppCardSession(record);
196	    return;
197	  }
198	  if (content.content.type !== "text") {
199	    // Mirrors `remoteEditMessage`'s own check — surface as an
200	    // UnsupportedError so dispatchSend warn-and-skips uniformly.
201	    throw UnsupportedError.content(
202	      "edit",
203	      "iMessage",
204	      `only text content can be edited (got "${content.content.type}")`
205	    );
206	  }
207	  const remote = clientForPhone(client, space.phone);
208	  await remoteEditMessage(remote, space.id, content.target.id, content.content);
209	};
