211	const handleUnsend = async (
212	  client: IMessageClient,
213	  space: { id: string; phone: string },
214	  content: Unsend
215	): Promise<void> => {
216	  if (isPollContent(content.target.content)) {
217	    // The SDK has no poll delete; mirrors the reply/react poll guards.
218	    throw UnsupportedError.action(
219	      "unsend",
220	      "iMessage",
221	      "iMessage polls cannot be unsent"
222	    );
223	  }
224	  const remote = clientForPhone(client, space.phone);
225	  const targetContent = content.target.content;
226	  if (targetContent.type === "reaction") {
227	    // Tapbacks are removed via `setReaction(..., false)` against the
228	    // original message, not by retracting the tapback message — so pass
229	    // the reaction's own target (the message that was reacted to). Same
230	    // unknown-cast widen as the reaction send branch.
231	    await remoteUnsendReaction(
232	      remote,
233	      space.id,
234	      targetContent.target as unknown as IMessageMessage,
235	      targetContent.emoji
