445	 * message. `action` labels the error and `pollNoun` is the plural used in the
446	 * poll-unsupported message.
447	 */
448	const remoteForMessageTarget = (
449	  client: IMessageClient,
450	  space: { phone: string },
451	  target: { content: { type: string } },
452	  action: string,
453	  pollNoun: string
454	): AdvancedIMessage => {
455	  if (isPollContent(target.content)) {
456	    throw UnsupportedError.action(
457	      action,
458	      "iMessage",
459	      `iMessage polls do not support ${pollNoun}`
460	    );
461	  }
462	  return clientForPhone(client, space.phone);
463	};
