465	export const imessage = definePlatform("iMessage", {
466	  config: configSchema,
467	
468	  static: {
469	    effect: {
470	      message: messageEffects,
471	    },
472	  },
473	
474	  lifecycle: {
475	    createClient: async ({
476	      config,
477	      projectId,
478	      projectSecret,
479	    }): Promise<IMessageClient> => {
480	      if (config.clients) {
481	        const entries = Array.isArray(config.clients)
482	          ? config.clients
483	          : [config.clients];
484	        // Branded like the cloud path so inbound routes through fusor —
485	        // note explicit-client setups carry no project credentials, so the
486	        // fusor stream can't be opened: outbound + spectrum.webhook() only.
487	        return fusorAttach(
488	          entries.map((e) => ({
489	            phone: e.phone,
490	            client: createClient({
491	              address: e.address,
492	              // Auto-retry transient unary failures (idempotency-keyed so retries
493	              // can't double-apply) so a server blip during an outbound action
494	              // doesn't crash the app.
495	              autoIdempotency: true,
496	              retry: true,
497	              tls: true,
498	              token: e.token,
499	            }),
500	          })),
501	          IMESSAGE_FUSOR_PLATFORM,
502	          verifyIMessage
503	        );
504	      }
505	
506	      if (!(projectId && projectSecret)) {
507	        throw new Error(
508	          "Cloud iMessage requires projectId and projectSecret. Pass credentials to Spectrum() or provide explicit clients with imessage.config({ clients: [...] }). For local Messages access, install @spectrum-ts/imessage-local and use its imessage.config()."
509	        );
510	      }
511	
512	      // In-place branding: the returned value stays the same RemoteClient[]
513	      // every send/action helper and WeakMap-keyed cache expects; the brand
514	      // additionally routes inbound through the fusor pipeline (verify →
515	      // messages) instead of a long-lived stream.
516	      return fusorAttach(
517	        await createCloudClients(projectId, projectSecret),
518	        IMESSAGE_FUSOR_PLATFORM,
519	        verifyIMessage
520	      );
521	    },
522	
523	    destroyClient: async ({ client }) => {
524	      await disposeCloudAuth(client);
525	      await Promise.all(client.map((entry) => entry.client.close()));
526	    },
527	  },
528	
529	  user: {
530	    schema: userSchema,
531	    resolve: async ({ input }) => ({ id: input.userID }),
532	  },
533	
534	  space: {
535	    schema: spaceSchema,
536	    params: spaceParamsSchema,
537	    create: async ({ input, client }) => {
538	      if (input.users.length === 0) {
539	        throw new Error("iMessage space creation requires at least one user");
540	      }
541	
542	      if (client.length === 0) {
543	        throw new Error("No iMessage clients configured");
544	      }
545	
546	      const addresses = input.users.map((u) => u.id);
547	
548	      // Shared mode: one identity at the SHARED_PHONE sentinel. DM guids are
549	      // deterministic (`any;-;{address}`), so no server call is needed — but
550	      // the shared gateway cannot create group chats.
551	      if (isSharedMode(client)) {
552	        if (addresses.length > 1) {
553	          throw UnsupportedError.action(
554	            "space.create",
555	            "iMessage (shared mode)",
556	            "shared mode cannot create group chats — use a dedicated number, or space.get(chatGuid) for an existing group"
557	          );
558	        }
559	        return {
560	          id: dmChatGuid(addresses[0] ?? ""),
561	          type: "dm" as const,
562	          phone: SHARED_PHONE,
563	        };
564	      }
565	
566	      // Dedicated mode: DMs and groups both go through the create API so the
567	      // server-issued guid is authoritative.
568	      const phone = input.params?.phone ?? randomPhone(client);
569	      const remote = clientForPhone(client, phone);
570	      const { chat } = await remote.chats.create(addresses);
571	      return {
572	        id: chat.guid,
573	        type: chat.isGroup ? ("group" as const) : ("dm" as const),
574	        phone,
575	      };
576	    },
577	    get: async ({ input, client }) => {
578	      if (client.length === 0) {
579	        throw new Error("No iMessage clients configured");
580	      }
581	      // No server call: the guid itself encodes the chat type, and sends
582	      // route by `phone`. Shared mode has a single identity, one configured
583	      // client is unambiguous, anything else needs an explicit phone.
584	      const phone = isSharedMode(client)
585	        ? SHARED_PHONE
586	        : (input.params?.phone ??
587	          (client.length === 1 ? client[0]?.phone : undefined));
588	      if (!phone) {
589	        throw new Error(
590	          `iMessage space.get requires params.phone when multiple clients are configured. Available: ${availablePhones(client).join(", ")}`
591	        );
592	      }
593	      return {
594	        id: input.id,
595	        type: chatTypeFromGuid(input.id),
596	        phone,
597	      };
598	    },
599	    actions: {
600	      // Sugar: `space.background(input, opts?)` →
601	      // `space.send(background(input, opts?))`. Routed through the universal
602	      // send pipeline so the canonical and sugar forms share behavior.
603	      background: async (
604	        space: Space,
605	        input: BackgroundInput,
606	        opts?: { mimeType?: string }
607	      ) => {
608	        await space.send(backgroundContent(input as never, opts));
609	      },
610	      // Sugar: `space.shareContactCard()` → `space.send(nativeContactCard())`.
611	      // Routed through the universal send pipeline so the canonical and sugar
612	      // forms share behavior. Shares the bot account's native contact card.
613	      shareContactCard: async (space: Space) => {
614	        await space.send(nativeContactCardContent());
615	      },
616	    },
617	  },
618	
619	  message: {
620	    schema: messageSchema,
621	  },
622	
623	  // Inbound rides Fusor: the fusor-branded client makes the runtime invoke
624	  // this per delivered envelope (never as a long-lived producer — local mode
625	  // now lives in @spectrum-ts/imessage-local). The cast reconciles the fusor
626	  // ctx shape with the producer-typed slot.
627	  messages: imessageMessages as unknown as EventProducer<
628	    IMessageMessage,
629	    IMessageClient,
630	    z.infer<typeof configSchema>
631	  >,
632	
633	  send: async ({ space, content, client }) => {
634	    if (content.type === "reply") {
635	      const remote = remoteForMessageTarget(
636	        client,
637	        space,
638	        content.target,
639	        "reply",
640	        "replies"
641	      );
642	      return cacheRemoteOutbound(
643	        remote,
644	        space,
645	        await remoteReplyToMessage(
646	          remote,
647	          space.id,
648	          content.target.id,
649	          content.content
650	        )
651	      );
652	    }
653	    if (content.type === "reaction") {
654	      const remote = remoteForMessageTarget(
655	        client,
656	        space,
657	        content.target,
658	        "react",
659	        "reactions"
660	      );
661	      // `content.target` is statically typed as the generic `Message`, but
662	      // execution only reaches this iMessage `send` action when the target
663	      // came from the iMessage stream — hence the unknown-cast widen.
664	      return cacheRemoteOutbound(
665	        remote,
666	        space,
667	        await remoteReactToMessage(
668	          remote,
669	          space.id,
670	          content.target as unknown as IMessageMessage,
671	          content.emoji
672	        )
673	      );
674	    }
675	    if (content.type === "typing") {
676	      await handleTyping(client, space, content.state);
677	      return;
678	    }
679	    if (content.type === "edit") {
680	      await handleEdit(client, space, content);
681	      return;
682	    }
683	    if (content.type === "unsend") {
684	      await handleUnsend(client, space, content);
685	      return;
686	    }
687	    if (content.type === "streamText") {
688	      return await handleStreamText(client, space, content);
689	    }
690	    if (content.type === "rename") {
691	      await handleRename(client, space, content);
692	      return;
693	    }
694	    if (content.type === "avatar") {
695	      await handleAvatar(client, space, content);
696	      return;
697	    }
698	    if (content.type === "addMember") {
699	      await handleAddMember(client, space, content);
700	      return;
701	    }
702	    if (content.type === "removeMember") {
703	      await handleRemoveMember(client, space, content);
704	      return;
705	    }
706	    if (content.type === "leaveSpace") {
707	      await handleLeaveSpace(client, space);
