24	/**
25	 * Verified fusor payload. `drop` marks well-formed envelopes this client
26	 * chooses not to process (unknown schema major, unrecognized change
27	 * variant) — the messages handler logs and skips them, so one odd event
28	 * never turns into an error reply to fusor.
29	 */
30	export type IMessageFusorPayload =
31	  | {
32	      kind: "event";
33	      event: IMessageInboundEvent;
34	      eventId: string;
35	      line: string;
36	    }
37	  | { kind: "drop"; reason: string };
