39	const parseEvent = (
40	  envelope: IMessageEnvelope
41	): IMessageInboundEvent | undefined => {
42	  switch (envelope.kind) {
43	    case "message":
44	      return parseMessageChangeEvent(envelope.event, envelope.sequence);
45	    case "poll":
46	      return parsePollChangeEvent(envelope.event, envelope.sequence);
47	    case "group":
48	      return parseGroupChangeEvent(envelope.event, envelope.sequence);
49	    case "chat":
50	      return parseChatChangeEvent(envelope.event, envelope.sequence);
