56	/**
57	 * The fusor `verify` hook: parse the synthetic request's JSON body against
58	 * the envelope schema (see `ENVELOPE.md`), gate the schema version, and
59	 * decode the rich event through the SDK's generated parsers. Throwing
60	 * rejects the event (fusor gets an error reply) — reserved for payloads
61	 * that are structurally NOT the contract; recognizable-but-unsupported
62	 * shapes become `drop` payloads instead.
63	 */
64	export const verifyIMessage: FusorVerify<IMessageFusorPayload> = (req) => {
65	  const envelope = imessageEnvelopeSchema.parse(
66	    JSON.parse(new TextDecoder().decode(req.rawBody))
67	  );
68	  if (envelope.schemaVersion !== IMESSAGE_ENVELOPE_SCHEMA_VERSION) {
69	    return {
70	      kind: "drop",
71	      reason: `unknown envelope schemaVersion ${envelope.schemaVersion}`,
72	    };
73	  }
74	  const event = parseEvent(envelope);
75	  if (!event) {
76	    return {
77	      kind: "drop",
78	      reason: `unrecognized ${envelope.kind} change variant`,
79	    };
80	  }
81	  return {
82	    kind: "event",
83	    event,
84	    eventId: envelope.eventId,
85	    line: envelope.line,
86	  };
87	};
