25	// Redelivery dedupe: fusor delivery is at-least-once (resume boundary
26	// redeliveries, publisher retries), and eventIds are stable across
27	// republishes precisely so consumers can do this. Bounded and keyed per
28	// client array — same ownership pattern as the message/poll caches.
29	const SEEN_EVENTS_LIMIT = 4096;
30	const seenByClient = new WeakMap<object, LRUCache<string, true>>();
31	const seenEvents = (owner: object): LRUCache<string, true> => {
32	  let cache = seenByClient.get(owner);
33	  if (!cache) {
34	    cache = new LRUCache<string, true>({ max: SEEN_EVENTS_LIMIT });
35	    seenByClient.set(owner, cache);
36	  }
37	  return cache;
38	};
