40	// Ported from the retired gRPC stream orchestration: an event authored by
41	// the current account (its own sends echoing back) must not surface as
42	// inbound. Shared mode has no per-line identity, so only `isFromMe` applies.
43	const isEventFromCurrentAccount = (
44	  event: Pick<MessageEvent | PollEvent | GroupEvent, "actor" | "isFromMe">,
45	  phone: string
46	): boolean =>
47	  event.isFromMe ||
48	  (phone !== SHARED_PHONE &&
49	    event.actor?.address !== undefined &&
50	    event.actor.address === phone);
