52	const handleEvent = async (
53	  clients: RemoteClient[],
54	  payload: Extract<IMessageFusorPayload, { kind: "event" }>,
55	  projectConfig: ProjectData | undefined
56	): Promise<FusorMessagesReturn> => {
57	  const phone = payload.line; // "shared" IS the SHARED_PHONE sentinel
58	  const remote = clientForPhone(clients, phone);
59	  const event = payload.event;
60	
61	  switch (event.type) {
62	    case "message.received": {
63	      if (event.message.isFromMe) {
64	        return;
65	      }
66	      // Project profiles that opt into iMessage sync push the bot's contact
67	      // card to any chat with fresh inbound (24h dedupe inside the tracker,
68	      // fire-and-forget) — ported from the stream path's onInbound hook.
69	      const inboundChatGuid = event.message.chatGuids?.[0];
70	      if (projectConfig?.profile?.imessageSynced === true && inboundChatGuid) {
71	        getContactShareTracker(remote).maybeShare(inboundChatGuid);
72	      }
73	      return await toInboundMessages(
74	        remote,
75	        getMessageCache(remote),
76	        event,
77	        phone
78	      );
79	    }
80	    case "message.reactionAdded": {
81	      if (isEventFromCurrentAccount(event, phone)) {
82	        return;
83	      }
84	      return await toReactionMessages(
85	        remote,
86	        getMessageCache(remote),
87	        event,
88	        phone
89	      );
90	    }
91	    case "poll.changed": {
92	      // Cache before the self-filter: our own poll activity still updates
93	      // local poll state even though it never surfaces as a message.
94	      const pollCache = getPollCache(clients);
95	      cachePollEvent(pollCache, event);
96	      if (isEventFromCurrentAccount(event, phone)) {
97	        return;
98	      }
99	      return await toPollDeltaMessages(remote, pollCache, event, phone);
100	    }
101	    case "group.changed": {
102	      // Self-check against the acting party — for a leave that is the leaver
103	      // (`event.actor` is often absent there), so the agent's own departure
104	      // via `space.leave()` doesn't echo back as an inbound event.
105	      const actor = groupEventActor(event);
106	      if (
107	        isEventFromCurrentAccount({ actor, isFromMe: event.isFromMe }, phone)
108	      ) {
109	        return;
110	      }
111	      return await toGroupEventMessages(remote, event, phone);
112	    }
