120	type FusorCtx = FusorMessagesCtx<IMessageFusorPayload, unknown, IMessageClient>;
121	
122	/**
123	 * The provider's `messages` slot. Every createClient path returns the
124	 * fusor-branded client array, so the runtime invokes this once per delivered
125	 * envelope with the verified payload — never as a long-lived producer.
126	 * (Local Messages access lives in @spectrum-ts/imessage-local.)
127	 */
128	export const imessageMessages = (
129	  ctx: FusorCtx
130	): FusorMessagesReturn | Promise<FusorMessagesReturn> => {
131	  if (!("payload" in ctx)) {
132	    throw new Error(
133	      "iMessage inbound rides Fusor — this slot never runs as a stream producer"
134	    );
135	  }
136	  const { payload, client, projectConfig } = ctx;
137	  if (payload.kind === "drop") {
138	    log.debug("imessage fusor: dropping event", {
139	      "spectrum.imessage.fusor.drop_reason": payload.reason,
140	    });
141	    return;
142	  }
143	  const seen = seenEvents(client);
144	  if (seen.has(payload.eventId)) {
145	    return;
146	  }
147	  seen.set(payload.eventId, true);
148	  return handleEvent(client, payload, projectConfig);
149	};
