42	function toReplyBytes(body: string | Uint8Array | undefined): Uint8Array {
43	  if (body === undefined) {
44	    return new Uint8Array(0);
45	  }
46	  if (typeof body === "string") {
47	    return new TextEncoder().encode(body);
48	  }
49	  return body;
50	}
