52	interface HandlerOutcome {
53	  errorReason?: string;
54	  ok: boolean;
55	  reply?: FusorReply;
56	}
57	
58	function combineReplies(outcomes: HandlerOutcome[]): InboundReply {
59	  const successes = outcomes.filter((o) => o.ok);
60	  if (successes.length === 0) {
61	    const firstFailure = outcomes[0];
62	    return {
63	      eventId: "",
64	      errorReason: firstFailure?.errorReason ?? "no handler succeeded",
65	      status: 0,
66	      headers: {},
67	      body: new Uint8Array(0),
68	    };
69	  }
70	
71	  let status = 0;
72	  const headers: Record<string, string> = {};
73	  let body: Uint8Array = new Uint8Array(0);
74	
75	  for (const outcome of successes) {
76	    const reply = outcome.reply;
77	    if (!reply) {
78	      continue;
79	    }
80	    if (reply.status !== undefined && reply.status > status) {
81	      status = reply.status;
82	    }
83	    if (reply.headers) {
84	      for (const [k, v] of Object.entries(reply.headers)) {
85	        headers[k.toLowerCase()] = v;
86	      }
87	    }
88	    const candidate = toReplyBytes(reply.body);
89	    if (candidate.length > 0) {
90	      body = candidate;
91	    }
92	  }
93	
94	  return {
95	    eventId: "",
96	    errorReason: "",
97	    status,
98	    headers,
99	    body,
100	  };
101	}
