103	// Route a handler's return value. A bare record (or `fusorEvent("messages", …)`)
104	// goes to the message sink (`deliver`, which the webhook path overrides);
105	// `fusorEvent(channel, …)` goes to its per-channel queue via `pushEvent` —
106	// always, on both transports, since the webhook handler is messages-only.
107	function routeHandlerResult(
108	  result: FusorMessagesReturn,
109	  handler: RegisteredFusorHandler,
110	  deliver: (record: ProviderMessageRecord) => void
111	): void {
112	  if (result === undefined) {
113	    return;
114	  }
115	  const items = Array.isArray(result) ? result : [result];
116	  for (const item of items) {
117	    if (!isFusorEvent(item)) {
118	      deliver(item);
119	      continue;
120	    }
121	    if (item.name === FUSOR_MESSAGES_CHANNEL) {
122	      deliver(item.data as ProviderMessageRecord);
123	    } else {
124	      handler.pushEvent(item.name, item.data);
125	    }
126	  }
127	}
