129	function runHandlerOnce<TPayload>(
130	  handler: RegisteredFusorHandler<TPayload>,
131	  parsedRequest: ParsedHttpRequest,
132	  deliver: (record: ProviderMessageRecord) => void = handler.pushMessage
133	): Promise<HandlerOutcome> {
134	  return (async () => {
135	    try {
136	      const payload = await handler.verify(parsedRequest);
137	      let reply: FusorReply | undefined;
138	      let respondCalled = false;
139	      let returned = false;
140	      const respond = (next: FusorReply): void => {
141	        if (returned) {
142	          log.warn("fusor.respond called after handler returned; ignoring");
143	          return;
144	        }
145	        if (respondCalled) {
146	          log.debug("fusor.respond called more than once; last call wins");
147	        }
148	        respondCalled = true;
149	        reply = next;
150	      };
151	      const result = await handler.messages({ payload, respond });
152	      returned = true;
153	
154	      routeHandlerResult(result, handler as RegisteredFusorHandler, deliver);
155	      return { ok: true, reply };
156	    } catch (error) {
157	      return { ok: false, errorReason: errorText(error) };
158	    }
159	  })();
160	}
