/**
 * Brand an existing object (e.g. a provider's long-lived client) as a
 * `FusorClient`, so a platform whose inbound rides fusor can still carry
 * the outbound state its `send`/`actions` need on the same object. Mutates
 * `carrier` in place — identity is preserved, so WeakMap-keyed caches keep
 * working. The `messages` handler reads it back via `ctx.client`.
 */
export function fusorAttach<TPayload, T extends object>(
  carrier: T,
  platform: string,
  verify: FusorVerify<TPayload>
): T & FusorClient<TPayload> {
  return Object.assign(carrier, {
    [FUSOR_BRAND]: true as const,
    platform,
    verify,
  });
}

