34	  if (clients.length === 0) {
35	    throw new Error("No iMessage phones configured for this account");
36	  }
37	  if (isSharedMode(clients)) {
38	    return SHARED_PHONE;
39	  }
40	  const entry = clients[Math.floor(Math.random() * clients.length)];
41	  if (!entry) {
42	    throw new Error("No iMessage phones configured for this account");
43	  }
