2	import {
3	  cloud,
4	  type DedicatedTokenData,
5	  type SharedTokenData,
6	} from "@spectrum-ts/core";
7	import { createLogger, errorAttrs } from "@spectrum-ts/core/authoring";
8	import { type RemoteClient, SHARED_PHONE } from "./types";
9	
10	const log = createLogger("spectrum.imessage.auth");
11	
12	const RENEWAL_RATIO = 0.8;
13	const EXPIRY_BUFFER_MS = 30_000;
14	const RETRY_DELAY_MS = 30_000;
15	
16	interface CloudAuth {
17	  dispose: () => void;
18	}
19	
20	const cloudAuthState = new WeakMap<RemoteClient[], CloudAuth>();
21	
22	const requirePhone = (data: DedicatedTokenData, instanceId: string): string => {
23	  const phone = data.numbers?.[instanceId];
24	  if (!phone) {
25	    throw new Error(`iMessage instance ${instanceId} has no phone assigned`);
26	  }
27	  return phone;
28	};
