30	export async function createCloudClients(
31	  projectId: string,
32	  projectSecret: string
33	): Promise<RemoteClient[]> {
34	  let tokenData = await cloud.issueImessageTokens(projectId, projectSecret);
35	  let tokenExpiresAt = Date.now() + tokenData.expiresIn * 1000;
36	  let disposed = false;
37	  let renewalTimer: ReturnType<typeof setTimeout> | undefined;
38	  let refreshFailures = 0;
39	  let refreshInFlight: Promise<void> | undefined;
40	
41	  // The instanceId stays paired with each entry in this closure so renewal
42	  // can rewrite `entry.phone` in place without leaking instanceId onto the
43	  // public RemoteClient shape. Empty in shared mode.
44	  const records: { entry: RemoteClient; instanceId: string }[] = [];
45	
46	  const syncPhones = (data: DedicatedTokenData) => {
47	    for (const { entry, instanceId } of records) {
48	      entry.phone = requirePhone(data, instanceId);
49	    }
50	  };
51	
52	  const onRefreshSuccess = () => {
53	    if (refreshFailures > 0) {
54	      log.info("imessage token refresh recovered", {
55	        "spectrum.imessage.auth.attempt": refreshFailures,
56	      });
57	      refreshFailures = 0;
58	    }
59	  };
60	
61	  const onRefreshFailure = (error: unknown) => {
62	    refreshFailures += 1;
63	    log.warn(
64	      "imessage token refresh failed; retrying",
65	      {
66	        "spectrum.imessage.auth.attempt": refreshFailures,
67	        "spectrum.imessage.auth.retry_in_ms": RETRY_DELAY_MS,
68	        ...errorAttrs(error),
69	      },
70	      error
71	    );
72	  };
73	
74	  const refreshNow = async (): Promise<void> => {
75	    tokenData = await cloud.issueImessageTokens(projectId, projectSecret);
76	    tokenExpiresAt = Date.now() + tokenData.expiresIn * 1000;
77	    if (tokenData.type === "dedicated") {
78	      syncPhones(tokenData);
79	    }
80	    onRefreshSuccess();
81	    scheduleRenewal();
82	  };
83	
84	  // Coalesce concurrent re-mints: the message + poll streams and the renewal
85	  // timer can all ask at once, but only one issueImessageTokens call should run.
86	  const coalescedRefresh = (): Promise<void> => {
87	    if (!refreshInFlight) {
88	      refreshInFlight = refreshNow().finally(() => {
89	        refreshInFlight = undefined;
90	      });
91	    }
92	    return refreshInFlight;
93	  };
94	
95	  const scheduleRenewal = () => {
96	    if (disposed) {
97	      return;
98	    }
99	    // Clear any prior timer first — refreshNow()/forceRefresh() can re-arm the
100	    // schedule, and leaving the old timer running would leak overlapping renewals.
101	    if (renewalTimer !== undefined) {
102	      clearTimeout(renewalTimer);
103	      renewalTimer = undefined;
104	    }
105	    const ttlMs = tokenData.expiresIn * 1000;
106	    const renewInMs = Math.max(ttlMs * RENEWAL_RATIO, 5000);
107	
108	    const runScheduledRefresh = () => {
109	      coalescedRefresh().catch((error) => {
110	        onRefreshFailure(error);
111	        if (disposed) {
112	          return;
113	        }
114	        // Retry the refresh itself after RETRY_DELAY_MS. Re-running
115	        // scheduleRenewal would instead wait another full renewal window (80%
116	        // of TTL), leaving the token stale/expired during an outage. On
117	        // success, refreshNow() re-arms the next renewal.
118	        renewalTimer = setTimeout(runScheduledRefresh, RETRY_DELAY_MS);
119	        renewalTimer?.unref?.();
120	      });
121	    };
122	
123	    renewalTimer = setTimeout(runScheduledRefresh, renewInMs);
124	    renewalTimer?.unref?.();
125	  };
126	
127	  scheduleRenewal();
128	
129	  const refreshIfNeeded = async (): Promise<void> => {
130	    if (Date.now() < tokenExpiresAt - EXPIRY_BUFFER_MS) {
131	      return;
132	    }
133	    await coalescedRefresh();
134	  };
135	
136	  const dispose = () => {
137	    disposed = true;
138	    if (renewalTimer !== undefined) {
139	      clearTimeout(renewalTimer);
140	      renewalTimer = undefined;
141	    }
142	  };
143	  const cloudAuth: CloudAuth = { dispose };
144	
145	  // Both modes dial the HTTP middleware (imessage-server-v2-http); dedicated
146	  // routing happens server-side via the SDK's `server` option, not by dialing
147	  // per-instance hosts.
148	  const address =
149	    process.env.SPECTRUM_IMESSAGE_ADDRESS ??
150	    "imessage.spectrum.photon.codes:443";
151	
152	  if (tokenData.type === "shared") {
153	    const entries: RemoteClient[] = [
154	      {
155	        phone: SHARED_PHONE,
156	        client: createClient({
157	          address,
158	          // Auto-retry transient unary failures so a brief server blip during
159	          // an outbound action (send/react/reply) doesn't surface as an
160	          // uncaught error. `autoIdempotency` attaches an x-idempotency-key to
161	          // mutating RPCs so the retry can't double-apply.
162	          autoIdempotency: true,
163	          retry: true,
164	          tls: true,
165	          token: async () => {
166	            await refreshIfNeeded();
167	            return (tokenData as SharedTokenData).token;
168	          },
169	        }),
170	      },
171	    ];
172	
173	    cloudAuthState.set(entries, cloudAuth);
174	
175	    return entries;
176	  }
177	
178	  const dedicated = tokenData;
179	  for (const [instanceId, token] of Object.entries(dedicated.auth)) {
180	    const entry: RemoteClient = {
181	      phone: requirePhone(dedicated, instanceId),
182	      client: createClient({
183	        address,
184	        autoIdempotency: true,
185	        retry: true,
186	        // Routes every call to this dedicated instance (x-photon-server).
187	        server: instanceId,
188	        tls: true,
189	        token: async () => {
190	          await refreshIfNeeded();
191	          const data = tokenData as DedicatedTokenData;
192	          return data.auth[instanceId] ?? token;
193	        },
194	      }),
195	    };
196	    records.push({ entry, instanceId });
197	  }
198	  const entries = records.map((r) => r.entry);
199	
200	  cloudAuthState.set(entries, cloudAuth);
201	
202	  return entries;
203	}
204	
205	export async function disposeCloudAuth(clients: RemoteClient[]): Promise<void> {
206	  const auth = cloudAuthState.get(clients);
207	  if (auth) {
208	    auth.dispose();
209	    cloudAuthState.delete(clients);
210	  }
211	}
