1	import type { Poll, PollChoice } from "@spectrum-ts/core";
2	import type { IMessageMessage } from "./types";
3	
4	const DEFAULT_MAX = 1000;
5	
6	export interface CachedPoll {
7	  readonly optionsByIdentifier: ReadonlyMap<string, PollChoice>;
8	  readonly poll: Poll;
9	}
10	
11	/**
12	 * Bounded insertion-order cache of recently-seen iMessage messages, keyed by
13	 * guid. Provides O(1) lookup for reaction target resolution. When capacity is
14	 * exceeded, the oldest entry is evicted. Access does not promote recency —
15	 * this is a bounded FIFO, not an LRU. The workload (reactions arriving shortly
16	 * after the message they target) doesn't benefit from LRU semantics, and FIFO
17	 * avoids a dependency.
18	 */
19	export class MessageCache {
20	  private readonly map = new Map<string, IMessageMessage>();
21	  private readonly max: number;
22	
23	  constructor(max = DEFAULT_MAX) {
24	    this.max = max;
25	  }
26	
27	  get(id: string): IMessageMessage | undefined {
28	    return this.map.get(id);
29	  }
30	
31	  set(id: string, message: IMessageMessage): void {
32	    if (this.map.has(id)) {
33	      this.map.delete(id);
34	    }
35	    this.map.set(id, message);
36	    if (this.map.size > this.max) {
37	      const first = this.map.keys().next().value;
38	      if (first !== undefined) {
39	        this.map.delete(first);
40	      }
41	    }
42	  }
43	
44	  clear(): void {
45	    this.map.clear();
46	  }
47	}
48	
49	/**
50	 * Bounded insertion-order cache of recently-seen iMessage polls, keyed by
51	 * poll message guid. The public poll shape deliberately hides provider ids;
52	 * `optionsByIdentifier` keeps the private lookup table needed to correlate
53	 * vote events back to public `PollChoice` objects.
54	 */
55	export class PollCache {
56	  private readonly map = new Map<string, CachedPoll>();
57	  private readonly max: number;
58	
59	  constructor(max = DEFAULT_MAX) {
60	    this.max = max;
61	  }
62	
63	  get(id: string): CachedPoll | undefined {
64	    return this.map.get(id);
65	  }
66	
67	  set(id: string, poll: CachedPoll): void {
68	    if (this.map.has(id)) {
69	      this.map.delete(id);
70	    }
71	    this.map.set(id, poll);
72	    if (this.map.size > this.max) {
73	      const first = this.map.keys().next().value;
74	      if (first !== undefined) {
75	        this.map.delete(first);
76	      }
77	    }
78	  }
79	
80	  clear(): void {
81	    this.map.clear();
82	  }
83	}
84	
85	const messageCaches = new WeakMap<object, MessageCache>();
86	const pollCaches = new WeakMap<object, PollCache>();
87	
88	/**
89	 * Returns a per-client message cache. Keyed by the client array so each
90	 * iMessage provider instance has its own cache and multiple providers don't
91	 * share state accidentally.
92	 */
93	export const getMessageCache = (owner: object): MessageCache => {
94	  let cache = messageCaches.get(owner);
95	  if (!cache) {
96	    cache = new MessageCache();
97	    messageCaches.set(owner, cache);
98	  }
99	  return cache;
100	};
101	
102	export const getPollCache = (owner: object): PollCache => {
103	  let cache = pollCaches.get(owner);
104	  if (!cache) {
105	    cache = new PollCache();
106	    pollCaches.set(owner, cache);
107	  }
108	  return cache;
109	};
