1	/**
2	 * A small per-platform key-value bag, modeled after Swift's `UserDefaults`.
3	 * Untyped writes; typed reads return `undefined` on missing key OR type
4	 * mismatch (no throws). In-memory only.
5	 *
6	 * SDK-internal: reachable from inside `definePlatform` callbacks via the
7	 * `store` field on lifecycle/action/event ctx. Not exposed on the public
8	 * SpectrumInstance or platform narrower.
9	 */
10	export interface Store {
11	  array<T = unknown>(key: string): T[] | undefined;
12	  bool(key: string): boolean | undefined;
13	  clear(): void;
14	  delete(key: string): boolean;
15	  get(key: string): unknown;
16	  has(key: string): boolean;
17	  keys(): string[];
18	  number(key: string): number | undefined;
19	  object<T = Record<string, unknown>>(key: string): T | undefined;
20	  set(key: string, value: unknown): void;
21	
22	  string(key: string): string | undefined;
23	}
24	
25	const isRecordObject = (value: unknown): value is Record<string, unknown> => {
26	  if (typeof value !== "object" || value === null || Array.isArray(value)) {
27	    return false;
28	  }
29	  const prototype = Object.getPrototypeOf(value);
30	  return prototype === Object.prototype || prototype === null;
31	};
32	
33	export function createStore(): Store {
34	  const data = new Map<string, unknown>();
35	
36	  return {
37	    set(key, value) {
38	      data.set(key, value);
39	    },
40	    get(key) {
41	      return data.get(key);
42	    },
43	    has(key) {
44	      return data.has(key);
45	    },
46	    delete(key) {
47	      return data.delete(key);
48	    },
49	    clear() {
50	      data.clear();
51	    },
52	    keys() {
53	      return Array.from(data.keys());
54	    },
55	    string(key) {
56	      const v = data.get(key);
57	      return typeof v === "string" ? v : undefined;
58	    },
59	    number(key) {
60	      const v = data.get(key);
61	      return typeof v === "number" ? v : undefined;
62	    },
63	    bool(key) {
64	      const v = data.get(key);
65	      return typeof v === "boolean" ? v : undefined;
66	    },
67	    object<T = Record<string, unknown>>(key: string): T | undefined {
68	      const v = data.get(key);
69	      if (!isRecordObject(v)) {
70	        return;
71	      }
72	      return v as T;
73	    },
74	    array<T = unknown>(key: string): T[] | undefined {
75	      const v = data.get(key);
76	      return Array.isArray(v) ? (v as T[]) : undefined;
77	    },
78	  };
79	}
