/** Replay window for the signed envelope timestamp (seconds). */
export const DEFAULT_REPLAY_TOLERANCE_SEC = 300;

export const configSchema = z.strictObject({
  clients: clientEntry.or(z.array(clientEntry)).optional(),
  /**
   * HMAC secret for the inner envelope signature (`x-imessage-signature` /
   * `x-imessage-timestamp` — see `fusor/ENVELOPE.md`). Optional: unsigned
   * envelopes are accepted only while no secret is configured; once set,
   * every delivery must carry a fresh, valid signature.
   */
  webhookSigningSecret: z.string().min(1).optional(),
