import { createHmac, timingSafeEqual } from "node:crypto";
import {
  type ChatEvent,
  type GroupEvent,
  type MessageEvent,
  type PollEvent,
  parseChatChangeEvent,
  parseGroupChangeEvent,
  parseMessageChangeEvent,
  parsePollChangeEvent,
} from "@photon-ai/advanced-imessage";
import type { FusorVerify, FusorVerifyRequest } from "@spectrum-ts/core";
import type { IMessageConfig } from "../types";
import {
  IMESSAGE_ENVELOPE_SCHEMA_VERSION,
  type IMessageEnvelope,
  imessageEnvelopeSchema,
} from "./envelope";

export type IMessageInboundEvent =
  | MessageEvent
  | PollEvent
  | GroupEvent
  | ChatEvent;

/**
 * Verified fusor payload. `drop` marks well-formed envelopes this client
 * chooses not to process (unknown schema major, unrecognized change
 * variant) — the messages handler logs and skips them, so one odd event
 * never turns into an error reply to fusor.
 */
export type IMessageFusorPayload =
  | {
      kind: "event";
      event: IMessageInboundEvent;
      eventId: string;
      line: string;
    }
  | { kind: "drop"; reason: string };

/** Signature headers on the publisher's synthetic request (lowercase). */
const TS_HEADER = "x-imessage-timestamp";
const SIG_HEADER = "x-imessage-signature";

const MS_PER_SEC = 1000;

const safeEqualHex = (a: string, b: string): boolean => {
  const left = Buffer.from(a, "hex");
  const right = Buffer.from(b, "hex");
  return (
    left.length > 0 && left.length === right.length && timingSafeEqual(left, right)
  );
};

/**
 * Inner-layer authenticity check (see `ENVELOPE.md` §Signature): HMAC-SHA256
 * over `{ts}.{body}` with a replay window around the signed timestamp.
 * Throws to reject — fusor treats the event as poison.
 */
const checkSignature = (
  req: FusorVerifyRequest,
  bodyText: string,
  secret: string,
  replayToleranceSec: number
): void => {
  const ts = req.headers[TS_HEADER];
  const sig = req.headers[SIG_HEADER];
  if (!(ts && sig)) {
    throw new Error("imessage envelope missing signature headers");
  }
  const tsNum = Number(ts);
  const ageSec = Math.abs(Date.now() / MS_PER_SEC - tsNum);
  if (!Number.isFinite(tsNum) || ageSec > replayToleranceSec) {
    throw new Error(
      "imessage envelope timestamp outside tolerance (possible replay)"
    );
  }
  const expected = createHmac("sha256", secret)
    .update(`${ts}.${bodyText}`)
    .digest("hex");
  if (!safeEqualHex(expected, sig)) {
    throw new Error("imessage envelope signature mismatch");
  }
};

const parseEvent = (
  envelope: IMessageEnvelope
): IMessageInboundEvent | undefined => {
