/**
 * Build the fusor `verify` hook: authenticate the raw bytes when a signing
 * secret is configured, then parse the synthetic request's JSON body against
 * the envelope schema (see `ENVELOPE.md`), gate the schema version, and
 * decode the rich event through the SDK's generated parsers. Throwing
 * rejects the event (fusor gets an error reply) — reserved for payloads
 * that are unauthentic or structurally NOT the contract;
 * recognizable-but-unsupported shapes become `drop` payloads instead.
 */
export const makeVerify =
  (config: IMessageConfig): FusorVerify<IMessageFusorPayload> =>
  (req) => {
    const bodyText = new TextDecoder().decode(req.rawBody);
    if (config.webhookSigningSecret) {
      checkSignature(
        req,
        bodyText,
        config.webhookSigningSecret,
        config.replayToleranceSec
      );
    }
    const envelope = imessageEnvelopeSchema.parse(JSON.parse(bodyText));
    if (envelope.schemaVersion !== IMESSAGE_ENVELOPE_SCHEMA_VERSION) {
      return {
        kind: "drop",
        reason: `unknown envelope schemaVersion ${envelope.schemaVersion}`,
      };
    }
    const event = parseEvent(envelope);
    if (!event) {
      return {
        kind: "drop",
        reason: `unrecognized ${envelope.kind} change variant`,
      };
    }
    return {
      kind: "event",
      event,
      eventId: envelope.eventId,
      line: envelope.line,
    };
  };

