type FusorCtx = FusorMessagesCtx<IMessageFusorPayload, unknown, IMessageClient>;

/**
 * The provider's `messages` slot. Every createClient path returns the
 * fusor-branded client array, so the runtime invokes this once per delivered
 * envelope with the verified payload — never as a long-lived producer.
 * (Local Messages access lives in @spectrum-ts/imessage-local.)
 */
export const imessageMessages = (
  ctx: FusorCtx
): FusorMessagesReturn | Promise<FusorMessagesReturn> => {
  if (!("payload" in ctx)) {
    throw new Error(
      "iMessage inbound rides Fusor — this slot never runs as a stream producer"
    );
  }
  const { payload, client, projectConfig } = ctx;
  if (payload.kind === "drop") {
    log.debug("imessage fusor: dropping event", {
      "spectrum.imessage.fusor.drop_reason": payload.reason,
    });
    return;
  }
  const seen = seenEvents(client);
  if (seen.has(payload.eventId)) {
    return;
  }
  seen.set(payload.eventId, true);
  return handleEvent(client, payload, projectConfig);
};

