  createClient: async ({
    config,
    projectId,
    projectSecret,
    store,
  }): Promise<FusorClient<IMessageFusorPayload>> => {
    if (config.clients) {
      const entries = Array.isArray(config.clients)
        ? config.clients
        : [config.clients];
      // Note explicit-client setups carry no project credentials, so the
      // fusor stream can't be opened: outbound + spectrum.webhook() only.
      initClients(
        store,
        entries.map((e) => ({
          phone: e.phone,
          client: createClient({
            address: e.address,
            // Auto-retry transient unary failures (idempotency-keyed so retries
            // can't double-apply) so a server blip during an outbound action
            // doesn't crash the app.
            autoIdempotency: true,
            retry: true,
            tls: true,
            token: e.token,
          }),
        }))
      );
      return fusor<IMessageFusorPayload>(
        IMESSAGE_FUSOR_PLATFORM,
        makeVerify(config)
      );
    }

    if (!(projectId && projectSecret)) {
      throw new Error(
        "Cloud iMessage requires projectId and projectSecret. Pass credentials to Spectrum() or provide explicit clients with imessage.config({ clients: [...] }). For local Messages access, install @spectrum-ts/imessage-local and use its imessage.config()."
      );
    }

    initClients(store, await createCloudClients(projectId, projectSecret));
    return fusor<IMessageFusorPayload>(
      IMESSAGE_FUSOR_PLATFORM,
      makeVerify(config)
    );
  },

  destroyClient: async ({ store }) => {
    // Tolerate a createClient that threw before initClients ran.
    const clients = peekClients(store);
    if (!clients) {
      return;
    }
    await disposeCloudAuth(clients);
    await Promise.all(clients.map((entry) => entry.client.close()));
  },
},

