/**
 * Inner-envelope signing options (ENVELOPE.md §Signature): HMAC-SHA256 over
 * `{ts}.{body}` carried as `x-imessage-timestamp` / `x-imessage-signature`.
 * `timestampSec` defaults to now; pass a stale value to test the replay
 * guard, or `signature` to force a mismatching header.
 */
export interface IMessageSignOptions {
  secret: string;
  signature?: string;
  timestampSec?: number;
}

