const MS_PER_SEC = 1000;

const signatureHeaders = (
  bodyText: string,
  sign: IMessageSignOptions
): string => {
  const ts = sign.timestampSec ?? Math.floor(Date.now() / MS_PER_SEC);
  const sig =
    sign.signature ??
    createHmac("sha256", sign.secret).update(`${ts}.${bodyText}`).digest("hex");
  return `x-imessage-timestamp: ${ts}\r\nx-imessage-signature: ${sig}\r\n`;
};

/**
 * The synthetic HTTP/1.1 request string carried in RawInboundEvent.rawRequest
 * — exposed separately for driving a fusor ws test server's event frames.
 * Pass `sign` to emit the signed variant (what a secret-configured publisher
 * sends).
 */
export const imessageEnvelopeHttp = (
  input: IMessageEnvelopeInput,
  sign?: IMessageSignOptions
): string => {
  const { body } = buildEnvelope(input);
  const bodyText = JSON.stringify(body);
  const version = input.schemaVersion ?? 1;
  const signed = sign ? signatureHeaders(bodyText, sign) : "";
  return `POST /imessage HTTP/1.1\r\ncontent-type: application/json\r\nx-imessage-schema-version: ${version}\r\n${signed}\r\n${bodyText}`;
};

/** The full protobuf webhook body fusor delivers (RawInboundEvent bytes). */
export const encodeIMessageEnvelope = (
  input: IMessageEnvelopeInput,
  sign?: IMessageSignOptions
): Uint8Array => {
  const { eventId } = buildEnvelope(input);
  return RawInboundEvent.encode(
    RawInboundEvent.create({
      eventId,
      projectId: input.projectId ?? "proj",
      platform: IMESSAGE_FUSOR_PLATFORM,
      rawRequest: new TextEncoder().encode(imessageEnvelopeHttp(input, sign)),
    })
  ).finish();
};

