import {
  type AdvancedIMessage,
  NotFoundError,
} from "@photon-ai/advanced-imessage";
import type { FusorVerifyRequest, Store } from "@spectrum-ts/core";
import {
  groupChangedEnvelope,
  type IMessageEnvelopeInput,
  type IMessageSignOptions,
  imessageEnvelopeHttp,
  messageReceivedEnvelope,
  pollChangedEnvelope,
  pollCreatedEnvelope,
  reactionAddedEnvelope,
} from "@spectrum-ts/test-support/imessage-fusor";
import { describe, expect, it } from "vitest";
import { makeVerify } from "@/fusor/verify";
import { getClients, initClients } from "@/remote/client";
import { imessageMessages } from "@/remote/fusor";
import {
  configSchema,
  type IMessageConfig,
  type IMessageMessage,
  type RemoteClient,
} from "@/types";

// Drive the exact bytes the mock publisher emits through verify → messages,
// the same pipeline FusorCore runs per delivered envelope.

const NO_CLIENT_FOR_LINE = /No iMessage client serves/;
const SIGNING_SECRET = "whsec_test";
const MS_PER_SEC = 1000;

const defaultConfig = configSchema.parse({});
const signedConfig = configSchema.parse({
  webhookSigningSecret: SIGNING_SECRET,
});
const verifyIMessage = makeVerify(defaultConfig);

/** Split the mock publisher's HTTP/1.1 wire string into a verify request. */
const verifyRequest = (
  input: IMessageEnvelopeInput,
  sign?: IMessageSignOptions
): FusorVerifyRequest => {
  const wire = imessageEnvelopeHttp(input, sign);
  const [head = "", body = ""] = wire.split("\r\n\r\n");
  const headers: Record<string, string> = {};
  for (const line of head.split("\r\n").slice(1)) {
    const idx = line.indexOf(":");
    if (idx > 0) {
      headers[line.slice(0, idx).toLowerCase()] = line.slice(idx + 1).trim();
    }
  }
  return {
    headers,
    method: "POST",
    path: "/imessage",
    rawBody: new TextEncoder().encode(body),
  };
};

const fakeRemote = (): AdvancedIMessage =>
  ({
    messages: {
      get: () => {
        throw new NotFoundError("not found", {
          code: "messageNotFound",
          grpcCode: 5,
          retryable: false,
        });
      },
    },
  }) as unknown as AdvancedIMessage;

const makeClients = (phones: string[] = ["shared"]): RemoteClient[] =>
  phones.map((phone) => ({ phone, client: fakeRemote() }));

/** Minimal in-memory `Store` — only what `initClients`/`getClients` touch. */
const testStore = (): Store => {
  const data = new Map<string, unknown>();
  return {
    set: (key, value) => data.set(key, value),
    get: (key) => data.get(key),
    has: (key) => data.has(key),
    delete: (key) => data.delete(key),
    clear: () => data.clear(),
    keys: () => Array.from(data.keys()),
    string: () => undefined,
    number: () => undefined,
    bool: () => undefined,
    object: () => undefined,
    array: <T = unknown>(key: string): T[] | undefined => {
      const v = data.get(key);
      return Array.isArray(v) ? (v as T[]) : undefined;
    },
  };
};

const storeFor = (clients: RemoteClient[]): Store => {
  const store = testStore();
  initClients(store, clients);
  return store;
};

const runInbound = async (
  input: IMessageEnvelopeInput,
  store: Store,
  config: IMessageConfig = defaultConfig
): Promise<IMessageMessage[]> => {
  const payload = await makeVerify(config)(verifyRequest(input));
  const result = await imessageMessages({
    client: undefined,
    config,
    payload,
    projectConfig: undefined,
    respond: () => undefined,
    store,
  });
  if (result === undefined) {
    return [];
  }
  return (Array.isArray(result) ? result : [result]) as IMessageMessage[];
};

describe("makeVerify", () => {
  it("parses a message envelope into a typed event payload", async () => {
    const payload = await verifyIMessage(
      verifyRequest(messageReceivedEnvelope({ text: "yo", sequence: 42 }))
    );
    if (payload.kind !== "event") {
      throw new Error(`expected event payload, got ${payload.kind}`);
    }
    expect(payload.line).toBe("shared");
    expect(payload.eventId).toBe("im-test-42");
    if (payload.event.type !== "message.received") {
      throw new Error(`unexpected event type ${payload.event.type}`);
    }
    expect(payload.event.sequence).toBe(42);
    expect(payload.event.message.guid).toBe("spc-msg-1");
  });

  it("drops (not rejects) an unknown schema major", async () => {
    const payload = await verifyIMessage(
      verifyRequest({ ...messageReceivedEnvelope(), schemaVersion: 2 })
    );
    expect(payload.kind).toBe("drop");
  });

  it("drops an unrecognized change variant", async () => {
    const payload = await verifyIMessage(
      verifyRequest({
        kind: "message",
        event: {
          chatGuid: "any;-;x",
          occurredAt: "2026-07-11T00:00:00Z",
          isFromMe: false,
        },
      })
    );
    expect(payload.kind).toBe("drop");
  });

  it("rejects a body that is not the contract", () => {
    expect(() =>
      verifyIMessage({
        headers: {},
        method: "POST",
        path: "/imessage",
        rawBody: new TextEncoder().encode('{"nope":true}'),
      })
    ).toThrow();
  });
});

describe("makeVerify (signed envelopes)", () => {
  const signedVerify = makeVerify(signedConfig);

  it("accepts a correctly signed, fresh envelope", async () => {
    const payload = await signedVerify(
      verifyRequest(messageReceivedEnvelope({ text: "signed" }), {
        secret: SIGNING_SECRET,
      })
    );
    expect(payload.kind).toBe("event");
  });

  it("rejects a missing signature when a secret is configured", () => {
    expect(() =>
      signedVerify(verifyRequest(messageReceivedEnvelope()))
    ).toThrow(/missing signature/);
  });

  it("rejects a tampered signature", () => {
    expect(() =>
      signedVerify(
        verifyRequest(messageReceivedEnvelope(), {
          secret: SIGNING_SECRET,
          signature: "0".repeat(64),
        })
      )
    ).toThrow(/signature mismatch/);
  });

  it("rejects a signature minted with the wrong secret", () => {
    expect(() =>
      signedVerify(
        verifyRequest(messageReceivedEnvelope(), { secret: "whsec_other" })
      )
    ).toThrow(/signature mismatch/);
  });

  it("rejects a stale timestamp (replay guard)", () => {
    const staleSec =
      Math.floor(Date.now() / MS_PER_SEC) -
      (defaultConfig.replayToleranceSec + 60);
    expect(() =>
      signedVerify(
        verifyRequest(messageReceivedEnvelope(), {
          secret: SIGNING_SECRET,
          timestampSec: staleSec,
        })
      )
    ).toThrow(/outside tolerance/);
  });

  it("still accepts unsigned envelopes when no secret is configured", async () => {
    const payload = await verifyIMessage(
      verifyRequest(messageReceivedEnvelope())
    );
    expect(payload.kind).toBe("event");
  });
});

describe("imessageMessages (fusor path)", () => {
  it("resolves message.received into an inbound record on the right line", async () => {
    const records = await runInbound(
      messageReceivedEnvelope({ text: "hello fusor" }),
      storeFor(makeClients())
    );
    expect(records).toHaveLength(1);
    const record = records[0];
    expect(record?.content).toMatchObject({
      type: "text",
      text: "hello fusor",
    });
    expect(record?.space.id).toBe("any;-;+12094503665");
    expect(record?.space.phone).toBe("shared");
    expect(record?.direction).toBe("inbound");
  });

  it("filters events authored by the current account", async () => {
    const records = await runInbound(
      messageReceivedEnvelope({ isFromMe: true }),
      storeFor(makeClients())
    );
    expect(records).toHaveLength(0);
  });

  it("demuxes dedicated lines by the envelope's line field", async () => {
    const store = storeFor(makeClients(["+14156035192", "+15550000000"]));
    const records = await runInbound(
      messageReceivedEnvelope({ line: "+14156035192", text: "dedicated" }),
      store
    );
    expect(records).toHaveLength(1);
    expect(records[0]?.space.phone).toBe("+14156035192");
  });

  it("rejects an event for a line no client serves", async () => {
    await expect(
      runInbound(
        messageReceivedEnvelope({ line: "+19999999999" }),
        storeFor(makeClients(["+14156035192", "+15550000000"]))
      )
    ).rejects.toThrow(NO_CLIENT_FOR_LINE);
  });

  it("dedupes redeliveries by eventId", async () => {
    const store = storeFor(makeClients());
    const envelope = messageReceivedEnvelope({ sequence: 77 });
    const first = await runInbound(envelope, store);
    const second = await runInbound(envelope, store);
    expect(first).toHaveLength(1);
    expect(second).toHaveLength(0);
  });

  it("caches the message so a later reaction resolves its target", async () => {
    const store = storeFor(makeClients());
    await runInbound(
      messageReceivedEnvelope({ guid: "spc-target-1", text: "react to me" }),
      store
    );
    const records = await runInbound(
      reactionAddedEnvelope({ messageGuid: "spc-target-1", sequence: 2 }),
