    );
    expect(records).toHaveLength(1);
    expect(records[0]?.content.type).toBe("reaction");
  });

  it("caches poll creation (even self-authored) and surfaces a later vote", async () => {
    const store = storeFor(makeClients());
    // The creation event is isFromMe — it must not surface as a message,
    // but it MUST populate the poll cache the vote below resolves against.
    const created = await runInbound(pollCreatedEnvelope({ sequence: 3 }), store);
    expect(created).toHaveLength(0);
    const records = await runInbound(
      pollChangedEnvelope({ optionIdentifier: "opt-2", sequence: 4 }),
      store
    );
    expect(records).toHaveLength(1);
  });

  it("surfaces a group participant change", async () => {
    const records = await runInbound(
      groupChangedEnvelope(),
      storeFor(makeClients())
    );
    expect(records).toHaveLength(1);
    expect(records[0]?.space.id).toBe("any;+;group123");
  });

  it("drops unknown-major envelopes silently", async () => {
    const records = await runInbound(
      { ...messageReceivedEnvelope(), schemaVersion: 9 },
      storeFor(makeClients())
    );
    expect(records).toHaveLength(0);
  });

  it("throws before createClient has stashed the clients", () => {
    expect(() => getClients(testStore())).toThrow(/not initialized/);
  });
});

