/** Minimal in-memory `Store` — enough for `initClients`/`getClients`. */
export const testStore = (): Store => {
  const data = new Map<string, unknown>();
  return {
    set: (key, value) => data.set(key, value),
    get: (key) => data.get(key),
    has: (key) => data.has(key),
    delete: (key) => data.delete(key),
    clear: () => data.clear(),
    keys: () => Array.from(data.keys()),
    string: () => undefined,
    number: () => undefined,
    bool: () => undefined,
    object: () => undefined,
    array: <T = unknown>(key: string): T[] | undefined => {
      const v = data.get(key);
      return Array.isArray(v) ? (v as T[]) : undefined;
    },
  };
};

/**
 * A store pre-seeded the way `lifecycle.createClient` seeds it — the
 * outbound `RemoteClient[]` under the clients key. What `send`/actions/
 * `space.*`/`messages` read via `getClients(store)`.
 */
export const storeWithClients = (clients: RemoteClient[]): Store => {
  const store = testStore();
  initClients(store, clients);
  return store;
};

