import { stubCloud } from "@spectrum-ts/test-support/cloud";
import {
  encodeIMessageEnvelope,
  messageReceivedEnvelope,
} from "@spectrum-ts/test-support/imessage-fusor";
import { baseConfig } from "@spectrum-ts/test-support/platform";
import { Spectrum } from "@spectrum-ts/core";
import type { Message } from "@spectrum-ts/core";
import { describe, expect, it } from "vitest";
import { imessage } from "@/index";

stubCloud();

// End-to-end over the webhook transport: the mock publisher's
// RawInboundEvent bytes → spectrum.webhook → verify → messages → the
// delivered [space, message]. Explicit clients (no cloud token mint); the
// text-only envelope never touches the outbound API.

const SIGNING_SECRET = "whsec_e2e";

const CLIENTS = { address: "localhost:1", token: "t", phone: "shared" };

const boot = (config: Parameters<typeof imessage.config>[0] = {}) =>
  Spectrum({
    ...baseConfig,
    providers: [imessage.config({ clients: CLIENTS, ...config })],
  });

describe("imessage over spectrum.webhook", () => {
  it("delivers an inbound text as [space, message] with platform 'imessage'", async () => {
    const spectrum = await boot();
    const received: [unknown, Message][] = [];
    const { promise: finished, resolve: done } = Promise.withResolvers<void>();

    const result = await spectrum.webhook(
      {
        headers: { "content-type": "application/x-protobuf" },
        body: encodeIMessageEnvelope(
          messageReceivedEnvelope({ text: "over the wire" })
        ),
      },
      (space, message) => {
        received.push([space, message]);
        done();
      }
    );
    await finished;

    expect(result.status).toBe(200);
    expect(received).toHaveLength(1);
    const first = received.at(0);
    if (!first) {
      throw new Error("expected one delivered message");
    }
    const [space, message] = first;
    expect(message.platform).toBe("imessage");
    expect((space as { __platform: string }).__platform).toBe("imessage");
    expect(message.content).toMatchObject({
      type: "text",
      text: "over the wire",
    });
    expect(message.direction).toBe("inbound");

    await spectrum.stop();
  });

  it("accepts a signed envelope when the secret is configured", async () => {
    const spectrum = await boot({ webhookSigningSecret: SIGNING_SECRET });
    const { promise: finished, resolve: done } = Promise.withResolvers<void>();

    const result = await spectrum.webhook(
      {
        headers: { "content-type": "application/x-protobuf" },
        body: encodeIMessageEnvelope(
          messageReceivedEnvelope({ text: "signed" }),
          { secret: SIGNING_SECRET }
        ),
      },
      () => done()
    );
    await finished;

    expect(result.status).toBe(200);
    await spectrum.stop();
  });

  it("returns 400 (poison) for an unsigned envelope when the secret is configured", async () => {
    const spectrum = await boot({ webhookSigningSecret: SIGNING_SECRET });

    const result = await spectrum.webhook(
      {
        headers: { "content-type": "application/x-protobuf" },
        body: encodeIMessageEnvelope(messageReceivedEnvelope()),
      },
      () => {
        throw new Error("must not deliver an unauthenticated envelope");
      }
    );

    expect(result.status).toBe(400);
    await spectrum.stop();
  });
});

